def maxAdjacentDistance(nums: List[int]) -> int:
    max_distance = 0
    length = len(nums)
    for i in range(length):
        next_index = (i + 1) % length
        distance = abs(nums[i] - nums[next_index])
        if distance > max_distance:
            max_distance = distance
    return max_distance

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        a, b = s[i], s[i + 1]
        if a != b and counts[a] == int(a) and counts[b] == int(b):
            return a + b
    return ""

