def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict
    count = defaultdict(int)
    n = len(nums)

    # Count appearances of each number in k-sized subarrays
    for i in range(n - k + 1):
        seen = set()
        for j in range(k):
            seen.add(nums[i + j])
        for num in seen:
            count[num] += 1

    # Find the largest number that appears in exactly one subarray
    result = -1
    for num, cnt in count.items():
        if cnt == 1:
            result = max(result, num)

    return result

