def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[float('-inf')] * 3 for _ in range(n)] for _ in range(m)]  # dp[i][j][k]: max coins using k neutralizations

    # Initialize the starting point
    if coins[0][0] >= 0:
        dp[0][0][0] = coins[0][0]
    else:
        dp[0][0][0] = coins[0][0]  # Take the hit
        dp[0][0][1] = 0  # Neutralize it

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            val = coins[i][j]
            for k in range(3):
                # Max profit from a predecessor (up or left) with k neutralizations
                prev_profit_k = float('-inf')
                if i > 0:
                    prev_profit_k = max(prev_profit_k, dp[i-1][j][k])
                if j > 0:
                    prev_profit_k = max(prev_profit_k, dp[i][j-1][k])

                # Option 1: Don't neutralize at (i,j) (collect coin or take hit)
                profit_no_neutralize = float('-inf')
                if prev_profit_k != float('-inf'):
                    profit_no_neutralize = prev_profit_k + val

                # Option 2: Neutralize at (i,j)
                profit_neutralize = float('-inf')
                if val < 0 and k > 0:
                    # Max profit from a predecessor with k-1 neutralizations
                    prev_profit_k_minus_1 = float('-inf')
                    if i > 0:
                        prev_profit_k_minus_1 = max(prev_profit_k_minus_1, dp[i-1][j][k-1])
                    if j > 0:
                        prev_profit_k_minus_1 = max(prev_profit_k_minus_1, dp[i][j-1][k-1])

                    if prev_profit_k_minus_1 != float('-inf'):
                        profit_neutralize = prev_profit_k_minus_1

                # The final value for dp[i][j][k] is the max of the two options.
                # If the cell is not a robber, only the first option is possible.
                if val >= 0:
                    dp[i][j][k] = profit_no_neutralize
                else:
                    dp[i][j][k] = max(profit_no_neutralize, profit_neutralize)

    # Return the maximum profit possible at the bottom-right corner
    return max(dp[m-1][n-1])

