def minCost(n: int, cost: List[List[int]]) -> int:
    # Store the minimum costs in a DP array
    dp = [[0] * 3 for _ in range(n)]

    # Fill the first house costs
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Iterate through houses 1 to n-1
    for i in range(1, n):
        for j in range(3):
            # Initialize with a large number
            dp[i][j] = float('inf')
            for k in range(3):
                if j != k:  # Adjacent houses cannot have the same color
                    dp[i][j] = min(dp[i][j], dp[i - 1][k] + cost[i][j])

        # Ensure equidistant color constraints
        if i % 2 == 1:  # For second set of houses
            for j in range(3):
                for k in range(3):
                    if j != k:
                        dp[i][j] = min(dp[i][j], dp[i - 2][k] + cost[i][j])

    # Calculate the minimum cost while respecting equidistant conditions
    final_cost = float('inf')
    for j in range(3):
        # Check last house and its pair with first half equidistant
        if dp[n - 1][j] < final_cost:
            opposite_color_choice = dp[n - 2][(j + 1) % 3]
            if opposite_color_choice < float('inf'):
                final_cost = min(final_cost, dp[n - 1][j] + opposite_color_choice)

    return final_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers  # Initialize mentions for each user
    online_status = [True] * numberOfUsers  # Track online status of each user
    offline_until = [0] * numberOfUsers  # Track when each user comes back online

    # Sort events by timestamp, with OFFLINE events before MESSAGE events if they occur at the same time
    events.sort(key=lambda e: (int(e[1]), e[0] == "MESSAGE"))

    for event in events:
        event_type, timestamp, detail = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(detail)
            # Set user offline
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            # Process user statuses that change before this message
            for user_id in range(numberOfUsers):
                if not online_status[user_id] and timestamp >= offline_until[user_id]:
                    online_status[user_id] = True

            # Handle mentions in message
            mentions_string = detail.split()  # Split mentions string into tokens

            for token in mentions_string:
                if token.startswith("id"):
                    user_id = int(token[2:])
                    mentions[user_id] += 1  # Count mention
                elif token == "ALL":
                    for user_id in range(numberOfUsers):
                        mentions[user_id] += 1  # Count mention for all users
                elif token == "HERE":
                    for user_id in range(numberOfUsers):
                        if online_status[user_id]:
                            mentions[user_id] += 1  # Count mention only for online users

    return mentions

