def maxFrequency(nums: List[int], k: int) -> int:
    from collections import Counter

    count = Counter(nums)
    initial_count = count[k]
    max_gain = 0

    # Iterate through possible values v to convert to k
    for v in range(1, 51):
        if v != k:
            current_gain = 0
            total_gain = 0

            for num in nums:
                if num == v:
                    current_gain += 1
                elif num == k:
                    current_gain -= 1
                total_gain = max(total_gain, current_gain)

                # Reset if current_gain drops below 0
                if current_gain < 0:
                    current_gain = 0

            max_gain = max(max_gain, total_gain)

    return initial_count + max_gain

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0

    # Iterate through the path
    for char in s:
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1

        # Calculate current Manhattan distance
        current_distance = abs(x) + abs(y)
        max_distance = max(max_distance, current_distance)

    # Maximum possible distance is the current distance + k moves of +1 in any direction
    # Each change can extend the distance by at most 2
    if k > 0:
        current_distance += min(k, (max_distance)) * 2

    return current_distance
